{
  "name": "openport",
  "params": {
    "port_id": "{{port_id}}",
    "select": {
      "category": ["{{category}}"]  // repeat for more categories
      // , "content": ""  // select by content code instead
    }
    // , "req_time": "{{req_time}}"
    // , "port_mode": ""  // e.g. SEQUENCE
  }
}

{
  "name": "openbin",
  "params": {
    "port_id": "{{port_id}}"
    // , "bin_id": "{{bin_id}}"  // ad-hoc bin
    // , "task_id": "{{task_id}}"
    // , "taskgroup_id": "{{taskgroup_id}}"  // resume a suspended group
    // , "shipment": "{{shipment}}"
  }
}

{
  "name": "closebin",
  "params": {
    "port_id": "{{port_id}}",
    "bin_id": "{{bin_id}}"
    // , "task_id": "{{task_id}}"  // recommended: without it bin mode can loop
    // , "content": ""
    // , "taskcomplete": true
  }
}

{
  "name": "closeport",
  "params": {
    "port_id": "{{port_id}}"
    // , "suspend_taskgroup": 1  // 1 = lock the group for a later resume
  }
}

{
  "name": "insertbin",
  "params": {
    "port_id": "{{port_id}}",
    "bin_id": "{{bin_id}}"
    // , "content": ""
    // , "bin_type": ""  // required the first time a bin is inserted
  }
}

